 await page.locator('#feedbackLeave').click();assert.equal(await page.locator('#welcome .primary:visible').count(),1);await page.reload({waitUntil:'networkidle'});await page.locator('#select-corporate').click();await page.getByRole('button',{name:'Continuar de onde parei',exact:true}).click();await page.locator('#feedback').waitFor({state:'visible'});assert.match(await page.locator('#feedbackCount').textContent(),/ETAPA 1 DE 6/);await page.locator('#continuePhase').click();await page.waitForFunction(()=>document.querySelector('#phaseCount').textContent.includes('ETAPA 2 DE'));
