 await choose('fechado',3);await choose('prometer',4);assert.match(await page.locator('#caseMaterials').textContent(),/horário ainda não confirmado/);assert.match(await page.locator('#caseMaterials').textContent(),/Entrega garantida/);await choose('repassar',5);await choose('encerrar',6);assert.match(await page.locator('#caseMaterials').textContent(),/Transferir a conversa/);
